/**
 * Copy Assets
 *
 * Publishes the game image assets that the app actually renders into the public
 * folder as WebP.
 *
 * The file list comes from asset_manifest.json, which is (re)generated by
 * build_asset_manifest.ts from src/configs and the UI code references, so
 * assets the app never loads never land in public. The public folder is wiped
 * before copying so removed assets cannot pile up.
 *
 * Encoding is hybrid: images up to 256 px (icons, headshots) are encoded
 * losslessly, larger artwork (formation/pile art) uses lossy quality 90 to keep
 * the app bundle small. The Pillow build that this replaced pinned libwebp
 * method 6 (lossless) and 5 (lossy); Bun.Image does not expose that knob, so
 * re-running this rewrites the published .webp files with slightly different
 * bytes (within a few percent either way).
 *
 * Run: bun scripts/copy_assets.ts
 */

import { existsSync, mkdirSync, readdirSync, rmSync } from "node:fs";
import { dirname, join } from "node:path";

import { buildAssetManifest } from "./build_asset_manifest.ts";
import { updateVersionField } from "./version_manifest.ts";

const SCRIPTS_DIR = import.meta.dirname;
const REPO_ROOT = join(SCRIPTS_DIR, "..");
const DATA_DIR = join(REPO_ROOT, "data");
const ASSETS_ROOT = join(DATA_DIR, "wuwa-assets");
const PUBLIC_ROOT = join(REPO_ROOT, "public", "wuwa-assets");
const MANIFEST_PATH = join(DATA_DIR, "asset_manifest.json");
const ASSETS_VERSION_PATH = join(ASSETS_ROOT, "VERSION.json");

// Encoding rules.
const LOSSLESS_MAX_DIM = 256;
const LOSSY_QUALITY = 90;

/** Convert one source PNG to WebP. Returns "lossy" or "lossless". */
async function encodeWebp(
	source: string,
	destination: string,
): Promise<"lossy" | "lossless"> {
	const { width, height } = await new Bun.Image(source).metadata();
	mkdirSync(dirname(destination), { recursive: true });

	if (Math.max(width, height) > LOSSLESS_MAX_DIM) {
		await new Bun.Image(source)
			.webp({ quality: LOSSY_QUALITY })
			.write(destination);
		return "lossy";
	}
	await new Bun.Image(source).webp({ lossless: true }).write(destination);
	return "lossless";
}

/** Mirror Path.with_suffix(".webp"). */
function toWebpPath(relative: string): string {
	return relative.replace(/\.[^./\\]+$/, ".webp");
}

/**
 * Point this repository's manifest at the game release the assets came from.
 *
 * `tools/wuwa-extract` in the wuwa-assets checkout writes the version it
 * extracted from into that repository's VERSION.json, so the `assets` entry
 * here is copied rather than hand-maintained.
 */
async function syncAssetsVersion(): Promise<void> {
	const assetsVersion = (await Bun.file(ASSETS_VERSION_PATH)
		.json()
		.catch(() => null)) as { game?: string } | null;

	if (!assetsVersion?.game) {
		console.warn(
			`warning: ${ASSETS_VERSION_PATH} is missing or has no "game"; VERSION.json left unchanged.`,
		);
		return;
	}

	await updateVersionField("assets", assetsVersion.game, ASSETS_VERSION_PATH);
}

function countFiles(dir: string): number {
	let total = 0;
	for (const entry of readdirSync(dir, { withFileTypes: true })) {
		if (entry.isDirectory()) total += countFiles(join(dir, entry.name));
		else total += 1;
	}
	return total;
}

/** Publish the assets referenced by the manifest to the public folder. */
async function copyAssets(): Promise<void> {
	console.log("=".repeat(60));
	console.log("Copy Assets to Public Folder");
	console.log("=".repeat(60));
	console.log();

	await syncAssetsVersion();

	// Regenerate the manifest so public always matches the current app code.
	await buildAssetManifest();
	console.log();

	const files = ((await Bun.file(MANIFEST_PATH).json()) as { files: string[] })
		.files;

	if (existsSync(PUBLIC_ROOT)) {
		const stale = countFiles(PUBLIC_ROOT);
		rmSync(PUBLIC_ROOT, { recursive: true, force: true });
		console.log(`🗑 Removed existing public assets (${stale} files)`);
	}

	let sourceBytes = 0;
	let outputBytes = 0;
	let lossyCount = 0;
	let index = 0;
	for (const relative of files) {
		index += 1;
		const source = join(ASSETS_ROOT, relative);
		const destination = join(PUBLIC_ROOT, toWebpPath(relative));

		if ((await encodeWebp(source, destination)) === "lossy") lossyCount += 1;
		sourceBytes += Bun.file(source).size;
		outputBytes += Bun.file(destination).size;

		if (index % 200 === 0 || index === files.length) {
			console.log(`   … converted ${index}/${files.length}`);
		}
	}

	console.log();
	console.log("=".repeat(60));
	console.log("✓ Asset copy complete!");
	console.log(
		`  Converted: ${files.length} PNGs -> WebP ` +
			`(${lossyCount} lossy, ${files.length - lossyCount} lossless)`,
	);
	console.log(
		`  Size:      ${(sourceBytes / 1024 / 1024).toFixed(1)} MiB -> ` +
			`${(outputBytes / 1024 / 1024).toFixed(1)} MiB`,
	);
	console.log("=".repeat(60));
}

if (import.meta.main) {
	await copyAssets();
}

export { copyAssets, syncAssetsVersion };
